"""Tests for tasks_api.models."""

from __future__ import annotations

from datetime import datetime, timedelta, timezone

import pytest

from tasks_api.models import Tag, Task, TaskPriority, TaskStatus


class TestTaskStatus:
    def test_values(self):
        assert TaskStatus.PENDING.value == "pending"
        assert TaskStatus.DONE.value == "done"

    def test_is_str_subclass(self):
        assert isinstance(TaskStatus.PENDING, str)


class TestTaskPriority:
    def test_values(self):
        assert TaskPriority.LOW.value == "low"
        assert TaskPriority.MEDIUM.value == "medium"
        assert TaskPriority.HIGH.value == "high"

    def test_order_key(self):
        assert TaskPriority.order_key(TaskPriority.HIGH) == 0
        assert TaskPriority.order_key(TaskPriority.MEDIUM) == 1
        assert TaskPriority.order_key(TaskPriority.LOW) == 2


class TestTag:
    def test_basic_creation(self):
        tag = Tag("python")
        assert tag.name == "python"

    def test_strips_and_lowercases(self):
        tag = Tag("  PyThon  ")
        assert tag.name == "python"

    def test_allows_hyphens_underscores_digits(self):
        tag = Tag("my-tag_123")
        assert tag.name == "my-tag_123"

    def test_rejects_non_string(self):
        with pytest.raises(TypeError, match="tag name must be a string"):
            Tag(123)

    def test_rejects_empty(self):
        with pytest.raises(ValueError, match="tag name must not be empty"):
            Tag("   ")

    def test_rejects_too_long(self):
        with pytest.raises(ValueError, match="32 characters"):
            Tag("a" * 33)

    def test_rejects_illegal_character(self):
        with pytest.raises(ValueError, match="illegal character"):
            Tag("hello world")

    def test_max_length_ok(self):
        tag = Tag("a" * 32)
        assert len(tag.name) == 32


class TestTask:
    def test_defaults(self):
        task = Task(id=1, title="Test")
        assert task.status == TaskStatus.PENDING
        assert task.priority == TaskPriority.MEDIUM
        assert task.due_at is None
        assert task.completed_at is None
        assert task.tags == []

    def test_is_overdue_no_due_date(self):
        now = datetime(2025, 6, 15, tzinfo=timezone.utc)
        task = Task(id=1, title="Test")
        assert task.is_overdue(now) is False

    def test_is_overdue_future(self):
        now = datetime(2025, 6, 15, tzinfo=timezone.utc)
        task = Task(id=1, title="Test", due_at=now + timedelta(days=1))
        assert task.is_overdue(now) is False

    def test_is_overdue_past(self):
        now = datetime(2025, 6, 15, tzinfo=timezone.utc)
        task = Task(id=1, title="Test", due_at=now - timedelta(days=1))
        assert task.is_overdue(now) is True

    def test_is_overdue_done_task(self):
        now = datetime(2025, 6, 15, tzinfo=timezone.utc)
        task = Task(
            id=1, title="Test",
            status=TaskStatus.DONE,
            due_at=now - timedelta(days=1),
        )
        assert task.is_overdue(now) is False
